-- Phase 1C1: immutable commercial allocation and instructor earnings foundation.
-- This migration is forward-only. It deliberately leaves all existing orders,
-- captures, refunds, chargebacks and access history untouched.

begin;

create table public.learning_commercial_terms (
  id bigint generated by default as identity primary key,
  version text not null unique check (version ~ '^[a-z][a-z0-9_-]{2,80}$'),
  scope_type text not null check (scope_type in ('platform','instructor','course')),
  instructor_id uuid references public.profiles(id) on delete restrict,
  course_id bigint references public.learning_courses(id) on delete restrict,
  commission_basis_points integer not null check (commission_basis_points between 0 and 10000),
  instructor_share_basis_points integer not null check (instructor_share_basis_points between 0 and 10000),
  earnings_hold_days integer not null check (earnings_hold_days between 0 and 365),
  reserve_basis_points integer check (reserve_basis_points is null or reserve_basis_points between 0 and 10000),
  active boolean not null default true,
  effective_at timestamptz not null default now(),
  retired_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles(id) on delete set null,
  constraint learning_commercial_terms_split_check check (commission_basis_points + instructor_share_basis_points = 10000),
  constraint learning_commercial_terms_scope_check check (
    (scope_type='platform' and instructor_id is null and course_id is null)
    or (scope_type='instructor' and instructor_id is not null and course_id is null)
    or (scope_type='course' and course_id is not null)
  ),
  constraint learning_commercial_terms_retired_check check ((active and retired_at is null) or (not active and retired_at is not null))
);
create unique index learning_commercial_terms_one_active_scope
  on public.learning_commercial_terms(scope_type, coalesce(instructor_id::text,''), coalesce(course_id::text,'')) where active;

insert into public.learning_commercial_terms(version,scope_type,commission_basis_points,instructor_share_basis_points,earnings_hold_days,reserve_basis_points,active)
values ('growvelt-commercial-v1','platform',2500,7500,14,null,true);

create table public.learning_commercial_allocations (
  id bigint generated by default as identity primary key,
  order_id bigint not null unique references public.learning_orders(id) on delete restrict,
  commercial_terms_version text not null references public.learning_commercial_terms(version) on delete restrict,
  instructor_id uuid not null references public.profiles(id) on delete restrict,
  course_id bigint references public.learning_courses(id) on delete restrict,
  gross_amount_minor bigint not null check (gross_amount_minor > 0),
  platform_commission_minor bigint not null check (platform_commission_minor >= 0),
  instructor_gross_minor bigint not null check (instructor_gross_minor >= 0),
  currency text not null check (currency='NGN'),
  allocation_ledger_transaction_id bigint not null unique references public.learning_ledger_transactions(id) on delete restrict,
  reversal_ledger_transaction_id bigint unique references public.learning_ledger_transactions(id) on delete restrict,
  status text not null default 'allocated' check (status in ('allocated','reversed')),
  allocated_at timestamptz not null default now(),
  reversed_at timestamptz,
  reversed_by_case_id bigint references public.learning_payment_cases(id) on delete restrict,
  constraint learning_commercial_allocations_amount_check check (gross_amount_minor=platform_commission_minor+instructor_gross_minor),
  constraint learning_commercial_allocations_reversal_check check ((status='allocated' and reversal_ledger_transaction_id is null and reversed_at is null and reversed_by_case_id is null) or (status='reversed' and reversal_ledger_transaction_id is not null and reversed_at is not null and reversed_by_case_id is not null))
);
create index learning_commercial_allocations_instructor_idx on public.learning_commercial_allocations(instructor_id,allocated_at desc,id desc);

create table public.learning_instructor_earnings (
  id bigint generated by default as identity primary key,
  allocation_id bigint not null unique references public.learning_commercial_allocations(id) on delete restrict,
  instructor_id uuid not null references public.profiles(id) on delete restrict,
  gross_amount_minor bigint not null check (gross_amount_minor > 0),
  currency text not null check (currency='NGN'),
  status text not null default 'held' check (status in ('held','available','reserved','paid','reversed','recoverable')),
  available_at timestamptz not null,
  released_at timestamptz,
  reserved_at timestamptz,
  paid_at timestamptz,
  reversed_at timestamptz,
  recoverable_amount_minor bigint not null default 0 check (recoverable_amount_minor between 0 and gross_amount_minor),
  hold_reason text,
  updated_at timestamptz not null default now(),
  constraint learning_instructor_earnings_lifecycle_check check (
    (status='held' and released_at is null and reserved_at is null and paid_at is null and reversed_at is null and recoverable_amount_minor=0)
    or (status='available' and released_at is not null and reserved_at is null and paid_at is null and reversed_at is null and recoverable_amount_minor=0)
    or (status='reserved' and reserved_at is not null and paid_at is null and reversed_at is null and recoverable_amount_minor=0)
    or (status='paid' and paid_at is not null and reversed_at is null and recoverable_amount_minor=0)
    or (status='reversed' and reversed_at is not null and recoverable_amount_minor=0)
    or (status='recoverable' and paid_at is not null and reversed_at is not null and recoverable_amount_minor=gross_amount_minor)
  )
);
create index learning_instructor_earnings_instructor_status_idx on public.learning_instructor_earnings(instructor_id,status,available_at,id);

create table public.learning_instructor_earning_events (
  id bigint generated by default as identity primary key,
  earning_id bigint not null references public.learning_instructor_earnings(id) on delete restrict,
  event_type text not null check (event_type ~ '^[a-z][a-z0-9_.]{2,80}$'),
  from_status text,
  to_status text,
  ledger_transaction_id bigint references public.learning_ledger_transactions(id) on delete restrict,
  payment_case_id bigint references public.learning_payment_cases(id) on delete restrict,
  actor_user_id uuid references public.profiles(id) on delete set null,
  note text,
  metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata)='object'),
  occurred_at timestamptz not null default now(),
  constraint learning_instructor_earning_events_note_check check (note is null or char_length(note)<=2000)
);
create index learning_instructor_earning_events_earning_idx on public.learning_instructor_earning_events(earning_id,occurred_at,id);

-- No rate is assumed. A later tax/payout phase may add a configured profile and
-- a separate compensating withholding transaction without rewriting earnings.
create table public.learning_instructor_withholding_profiles (
  instructor_id uuid primary key references public.profiles(id) on delete restrict,
  calculation_mode text not null default 'not_configured' check (calculation_mode in ('not_configured','percentage','fixed','exempt')),
  basis_points integer check (basis_points is null or basis_points between 0 and 10000),
  fixed_amount_minor bigint check (fixed_amount_minor is null or fixed_amount_minor>=0),
  effective_at timestamptz,
  classification_note text,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id) on delete set null,
  constraint learning_instructor_withholding_profile_mode_check check (
    (calculation_mode='not_configured' and basis_points is null and fixed_amount_minor is null)
    or (calculation_mode='percentage' and basis_points is not null and fixed_amount_minor is null)
    or (calculation_mode='fixed' and fixed_amount_minor is not null and basis_points is null)
    or (calculation_mode='exempt' and basis_points is null and fixed_amount_minor is null)
  ),
  constraint learning_instructor_withholding_profile_note_check check (classification_note is null or char_length(classification_note)<=2000)
);

alter table public.learning_commercial_terms enable row level security;
alter table public.learning_commercial_allocations enable row level security;
alter table public.learning_instructor_earnings enable row level security;
alter table public.learning_instructor_earning_events enable row level security;
alter table public.learning_instructor_withholding_profiles enable row level security;
revoke all on public.learning_commercial_terms,public.learning_commercial_allocations,public.learning_instructor_earnings,public.learning_instructor_earning_events,public.learning_instructor_withholding_profiles from public,anon,authenticated;
grant select,insert,update,delete on public.learning_commercial_terms,public.learning_commercial_allocations,public.learning_instructor_earnings,public.learning_instructor_earning_events,public.learning_instructor_withholding_profiles to postgres,service_role;

alter table public.learning_ledger_transactions drop constraint if exists learning_ledger_transactions_transaction_type_check;
alter table public.learning_ledger_transactions drop constraint if exists learning_ledger_transactions_type_check;
alter table public.learning_ledger_transactions add constraint learning_ledger_transactions_transaction_type_check check (transaction_type in ('payment_capture','processor_fee','refund','chargeback','adjustment','commercial_allocation','instructor_earnings_release','instructor_earnings_reversal'));

create or replace function public.prevent_learning_commercial_terms_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin
  if tg_op='DELETE' then raise exception 'Commercial terms history is retained and cannot be deleted' using errcode='42501'; end if;
  if old.version is distinct from new.version or old.scope_type is distinct from new.scope_type or old.instructor_id is distinct from new.instructor_id
    or old.course_id is distinct from new.course_id or old.commission_basis_points is distinct from new.commission_basis_points
    or old.instructor_share_basis_points is distinct from new.instructor_share_basis_points or old.earnings_hold_days is distinct from new.earnings_hold_days
    or old.reserve_basis_points is distinct from new.reserve_basis_points or old.effective_at is distinct from new.effective_at then
    raise exception 'Commercial term values are immutable; retire and create a new version' using errcode='42501';
  end if;
  if old.active and not new.active and new.retired_at is null then new.retired_at:=now(); end if;
  if not old.active and new.active then raise exception 'Retired commercial terms cannot be reactivated' using errcode='42501'; end if;
  return new;
end;$function$;
create trigger prevent_learning_commercial_terms_mutation before update or delete on public.learning_commercial_terms for each row execute function public.prevent_learning_commercial_terms_mutation();

create or replace function public.prevent_learning_commercial_allocation_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin
  if tg_op='DELETE' then raise exception 'Commercial allocation history is retained and cannot be deleted' using errcode='42501'; end if;
  if old.order_id is distinct from new.order_id or old.commercial_terms_version is distinct from new.commercial_terms_version
    or old.instructor_id is distinct from new.instructor_id or old.course_id is distinct from new.course_id
    or old.gross_amount_minor is distinct from new.gross_amount_minor or old.platform_commission_minor is distinct from new.platform_commission_minor
    or old.instructor_gross_minor is distinct from new.instructor_gross_minor or old.currency is distinct from new.currency
    or old.allocation_ledger_transaction_id is distinct from new.allocation_ledger_transaction_id then
    raise exception 'Commercial allocation financial identity is immutable' using errcode='42501';
  end if;
  if old.status='allocated' and new.status='reversed' then return new; end if;
  if old.status is distinct from new.status or old.reversal_ledger_transaction_id is distinct from new.reversal_ledger_transaction_id
    or old.reversed_at is distinct from new.reversed_at or old.reversed_by_case_id is distinct from new.reversed_by_case_id then
    raise exception 'Unsupported commercial allocation transition' using errcode='22023';
  end if;
  return new;
end;$function$;
create trigger prevent_learning_commercial_allocation_mutation before update or delete on public.learning_commercial_allocations for each row execute function public.prevent_learning_commercial_allocation_mutation();

create or replace function public.prevent_learning_instructor_earning_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin
  if tg_op='DELETE' then raise exception 'Instructor earning history is retained and cannot be deleted' using errcode='42501'; end if;
  if old.allocation_id is distinct from new.allocation_id or old.instructor_id is distinct from new.instructor_id or old.gross_amount_minor is distinct from new.gross_amount_minor or old.currency is distinct from new.currency or old.available_at is distinct from new.available_at then
    raise exception 'Instructor earning financial identity is immutable' using errcode='42501';
  end if;
  if old.status='held' and new.status in ('available','reserved','reversed') then new.updated_at:=now(); return new; end if;
  if old.status='available' and new.status in ('reserved','paid','reversed') then new.updated_at:=now(); return new; end if;
  if old.status='reserved' and new.status in ('available','paid','reversed') then new.updated_at:=now(); return new; end if;
  if old.status='paid' and new.status='recoverable' then new.updated_at:=now(); return new; end if;
  raise exception 'Unsupported instructor earning transition' using errcode='22023';
end;$function$;
create trigger prevent_learning_instructor_earning_mutation before update or delete on public.learning_instructor_earnings for each row execute function public.prevent_learning_instructor_earning_mutation();

create or replace function public.prevent_learning_instructor_earning_event_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin raise exception 'Instructor earning event history is append-only' using errcode='42501'; end;$function$;
create trigger prevent_learning_instructor_earning_event_mutation before update or delete on public.learning_instructor_earning_events for each row execute function public.prevent_learning_instructor_earning_event_mutation();

create or replace function public.resolve_learning_commercial_terms_version(p_course_id bigint,p_instructor_id uuid)
returns text language plpgsql stable security definer set search_path to '' as $function$
declare terms_version text;
begin
  select version into terms_version from public.learning_commercial_terms where scope_type='course' and course_id=p_course_id and active order by effective_at desc,id desc limit 1;
  if terms_version is null then select version into terms_version from public.learning_commercial_terms where scope_type='instructor' and instructor_id=p_instructor_id and active order by effective_at desc,id desc limit 1; end if;
  if terms_version is null then select version into terms_version from public.learning_commercial_terms where scope_type='platform' and active order by effective_at desc,id desc limit 1; end if;
  if terms_version is null then raise exception 'No active commercial terms are configured' using errcode='P0002'; end if;
  return terms_version;
end;$function$;

create or replace function public.allocate_learning_order_commercial_terms(p_order_id bigint,p_actor_user_id uuid default null)
returns bigint language plpgsql security definer set search_path to '' as $function$
declare order_row record; terms_row public.learning_commercial_terms%rowtype; allocation_key bigint; ledger_key bigint; earning_key bigint; commission_minor bigint; instructor_minor bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended('commercial-allocation:'||p_order_id::text,0));
  select o.* into order_row from public.learning_orders o where o.id=p_order_id for update;
  if not found then raise exception 'Order not found' using errcode='P0002'; end if;
  select id into allocation_key from public.learning_commercial_allocations where order_id=p_order_id;
  if found then return allocation_key; end if;
  if order_row.status<>'paid' or order_row.instructor_id is null or order_row.course_id is null or order_row.commercial_terms_version is null then
    raise exception 'Paid order with an instructor and commercial terms is required' using errcode='22023';
  end if;
  if not exists(select 1 from public.learning_ledger_transactions where order_id=p_order_id and transaction_type='payment_capture') then
    raise exception 'Payment capture ledger is required before allocation' using errcode='22023';
  end if;
  select * into terms_row from public.learning_commercial_terms where version=order_row.commercial_terms_version;
  -- Pre-Phase 1C orders retain their immutable historical terms snapshot and
  -- deliberately remain unallocated. They are not backfilled or recalculated.
  if not found then return null; end if;
  -- Canonical rounding: round Growvelt's component once to the nearest minor
  -- unit, then assign the exact remainder to the instructor. This keeps every
  -- present and future 10,000-basis-point split balanced.
  commission_minor:=round(order_row.gross_amount_minor*terms_row.commission_basis_points/10000.0)::bigint;
  instructor_minor:=order_row.gross_amount_minor-commission_minor;
  insert into public.learning_ledger_transactions(order_id,transaction_type,currency,description,created_by)
  values(p_order_id,'commercial_allocation',order_row.currency,'Immutable Growvelt platform and instructor commercial allocation',p_actor_user_id) returning id into ledger_key;
  insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values
    (ledger_key,1,'liability.marketplace_sales_unallocated',order_row.gross_amount_minor,order_row.currency,'learning_order',order_row.order_reference),
    (ledger_key,2,'revenue.platform_commission',-commission_minor,order_row.currency,'commercial_terms',terms_row.version),
    (ledger_key,3,'liability.instructor_earnings_held',-instructor_minor,order_row.currency,'instructor',order_row.instructor_id::text);
  insert into public.learning_commercial_allocations(order_id,commercial_terms_version,instructor_id,course_id,gross_amount_minor,platform_commission_minor,instructor_gross_minor,currency,allocation_ledger_transaction_id)
  values(p_order_id,terms_row.version,order_row.instructor_id,order_row.course_id,order_row.gross_amount_minor,commission_minor,instructor_minor,order_row.currency,ledger_key) returning id into allocation_key;
  insert into public.learning_instructor_earnings(allocation_id,instructor_id,gross_amount_minor,currency,status,available_at,hold_reason)
  values(allocation_key,order_row.instructor_id,instructor_minor,order_row.currency,'held',coalesce(order_row.paid_at,now())+make_interval(days=>terms_row.earnings_hold_days),'Standard 14-day commercial earnings hold') returning id into earning_key;
  insert into public.learning_instructor_earning_events(earning_id,event_type,to_status,ledger_transaction_id,actor_user_id,metadata)
  values(earning_key,'earning.held','held',ledger_key,p_actor_user_id,jsonb_build_object('commercial_terms_version',terms_row.version,'hold_days',terms_row.earnings_hold_days,'platform_commission_minor',commission_minor));
  insert into public.learning_audit_events(actor_user_id,actor_role,action,entity_type,entity_id,metadata)
  values(p_actor_user_id,case when p_actor_user_id is null then 'payment_system' else 'admin_operator' end,'commercial_allocation.created','commercial_allocation',allocation_key::text,jsonb_build_object('order_id',p_order_id,'terms_version',terms_row.version,'platform_commission_minor',commission_minor,'instructor_gross_minor',instructor_minor));
  return allocation_key;
end;$function$;

-- Availability is governed by database time only. A caller-supplied "as of"
-- time would allow a trusted service caller to bypass the approved 14-day hold.
drop function if exists public.release_matured_learning_instructor_earnings(timestamptz,integer,uuid);
create or replace function public.release_matured_learning_instructor_earnings(p_limit integer default 100,p_actor_user_id uuid default null)
returns integer language plpgsql security definer set search_path to '' as $function$
declare earning_row record; ledger_key bigint; released_count integer:=0;
begin
  if p_limit not between 1 and 1000 then raise exception 'Release limit is out of range' using errcode='22023'; end if;
  for earning_row in select e.*,a.order_id from public.learning_instructor_earnings e join public.learning_commercial_allocations a on a.id=e.allocation_id join public.learning_orders o on o.id=a.order_id
    where e.status='held' and e.available_at<=now() and a.status='allocated' and o.status='paid'
      and not exists(select 1 from public.learning_payment_cases c where c.order_id=a.order_id and c.status in ('requested','submitting','pending','processing','needs_attention','opened','action_required','submitted','under_review'))
    order by e.available_at,e.id for update of e skip locked limit p_limit
  loop
    insert into public.learning_ledger_transactions(order_id,transaction_type,currency,description,created_by)
    values(earning_row.order_id,'instructor_earnings_release',earning_row.currency,'Instructor earnings became available after the commercial hold',p_actor_user_id) returning id into ledger_key;
    insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values
      (ledger_key,1,'liability.instructor_earnings_held',earning_row.gross_amount_minor,earning_row.currency,'instructor_earning',earning_row.id::text),
      (ledger_key,2,'liability.instructor_earnings_available',-earning_row.gross_amount_minor,earning_row.currency,'instructor',earning_row.instructor_id::text);
    update public.learning_instructor_earnings set status='available',released_at=now(),hold_reason=null where id=earning_row.id;
    insert into public.learning_instructor_earning_events(earning_id,event_type,from_status,to_status,ledger_transaction_id,actor_user_id)
    values(earning_row.id,'earning.available','held','available',ledger_key,p_actor_user_id);
    released_count:=released_count+1;
  end loop;
  return released_count;
end;$function$;

create or replace function public.reverse_learning_order_commercial_allocation(p_order_id bigint,p_payment_case_id bigint,p_reason text,p_actor_user_id uuid default null)
returns bigint language plpgsql security definer set search_path to '' as $function$
declare allocation_row public.learning_commercial_allocations%rowtype; earning_row public.learning_instructor_earnings%rowtype; case_row public.learning_payment_cases%rowtype; order_gross_minor bigint; ledger_key bigint; instructor_account text;
begin
  -- A case is a financial authorization only when it belongs to this order and
  -- has reached the existing authoritative refund/dispute outcome.
  select * into case_row from public.learning_payment_cases
    where id=p_payment_case_id and order_id=p_order_id for update;
  if not found then raise exception 'Payment case does not belong to this order' using errcode='42501'; end if;
  select gross_amount_minor into order_gross_minor from public.learning_orders where id=p_order_id for share;
  if order_gross_minor is null then raise exception 'Order not found' using errcode='P0002'; end if;
  if case_row.case_type='refund' then
    if case_row.status<>'processed' or case_row.provider_status<>'processed'
      or case_row.amount_minor<>order_gross_minor or case_row.processed_amount_minor<>order_gross_minor then
      raise exception 'Authoritative processed refund case is required' using errcode='22023';
    end if;
  elsif case_row.case_type='chargeback' then
    if case_row.status<>'lost' or case_row.provider_status<>'resolved' or case_row.provider_resolution<>'merchant-accepted' then
      raise exception 'Authoritative lost chargeback case is required' using errcode='22023';
    end if;
    if case_row.amount_minor<>order_gross_minor then
      raise exception 'Partial chargeback commercial reversal is not supported' using errcode='22023';
    end if;
  else
    raise exception 'Only refund or chargeback cases can reverse commercial allocation' using errcode='22023';
  end if;
  select * into allocation_row from public.learning_commercial_allocations where order_id=p_order_id for update;
  if not found then return null; end if;
  if allocation_row.status='reversed' then return allocation_row.reversal_ledger_transaction_id; end if;
  select * into earning_row from public.learning_instructor_earnings where allocation_id=allocation_row.id for update;
  if not found then raise exception 'Commercial allocation has no instructor earning' using errcode='23514'; end if;
  if earning_row.status='held' then instructor_account:='liability.instructor_earnings_held';
  elsif earning_row.status='available' then instructor_account:='liability.instructor_earnings_available';
  elsif earning_row.status='reserved' then instructor_account:='liability.instructor_earnings_reserved';
  elsif earning_row.status='paid' then instructor_account:='asset.instructor_earnings_recoverable';
  else raise exception 'Instructor earning cannot be economically reversed in its current state' using errcode='22023'; end if;
  insert into public.learning_ledger_transactions(order_id,payment_case_id,transaction_type,currency,description,created_by)
  values(p_order_id,p_payment_case_id,'instructor_earnings_reversal',allocation_row.currency,'Compensating commercial allocation reversal: '||left(trim(p_reason),900),p_actor_user_id) returning id into ledger_key;
  insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values
    (ledger_key,1,'revenue.platform_commission',allocation_row.platform_commission_minor,allocation_row.currency,'commercial_allocation',allocation_row.id::text),
    (ledger_key,2,instructor_account,allocation_row.instructor_gross_minor,allocation_row.currency,'instructor_earning',earning_row.id::text),
    (ledger_key,3,'liability.marketplace_sales_unallocated',-allocation_row.gross_amount_minor,allocation_row.currency,'payment_case',p_payment_case_id::text);
  update public.learning_commercial_allocations set status='reversed',reversal_ledger_transaction_id=ledger_key,reversed_at=now(),reversed_by_case_id=p_payment_case_id where id=allocation_row.id;
  if earning_row.status='paid' then
    update public.learning_instructor_earnings set status='recoverable',reversed_at=now(),recoverable_amount_minor=earning_row.gross_amount_minor,hold_reason='Financial reversal after future payout' where id=earning_row.id;
    insert into public.learning_instructor_earning_events(earning_id,event_type,from_status,to_status,ledger_transaction_id,payment_case_id,actor_user_id,metadata) values(earning_row.id,'earning.recoverable','paid','recoverable',ledger_key,p_payment_case_id,p_actor_user_id,jsonb_build_object('reason',p_reason));
  else
    update public.learning_instructor_earnings set status='reversed',reversed_at=now(),hold_reason='Financial reversal: '||left(trim(p_reason),900) where id=earning_row.id;
    insert into public.learning_instructor_earning_events(earning_id,event_type,from_status,to_status,ledger_transaction_id,payment_case_id,actor_user_id,metadata) values(earning_row.id,'earning.reversed',earning_row.status,'reversed',ledger_key,p_payment_case_id,p_actor_user_id,jsonb_build_object('reason',p_reason));
  end if;
  insert into public.learning_audit_events(actor_user_id,actor_role,action,entity_type,entity_id,metadata)
  values(p_actor_user_id,case when p_actor_user_id is null then 'payment_system' else 'admin_operator' end,'commercial_allocation.reversed','commercial_allocation',allocation_row.id::text,jsonb_build_object('order_id',p_order_id,'payment_case_id',p_payment_case_id,'ledger_transaction_id',ledger_key));
  return ledger_key;
end;$function$;

create or replace function public.reconcile_learning_commercial_allocations()
returns table(issue_type text,order_reference text,detail text) language sql stable security definer set search_path to '' as $function$
  select 'allocated_order_missing_allocation',o.order_reference,'Paid order with a recognized commercial terms version has no allocation' from public.learning_orders o
  where o.status='paid' and exists(select 1 from public.learning_commercial_terms t where t.version=o.commercial_terms_version) and not exists(select 1 from public.learning_commercial_allocations a where a.order_id=o.id)
  union all select 'allocation_amount_mismatch',o.order_reference,'Allocation does not exactly split its order gross amount' from public.learning_commercial_allocations a join public.learning_orders o on o.id=a.order_id where a.gross_amount_minor<>o.gross_amount_minor or a.gross_amount_minor<>a.platform_commission_minor+a.instructor_gross_minor
  union all select 'allocation_missing_earning',o.order_reference,'Commercial allocation has no instructor earning row' from public.learning_commercial_allocations a join public.learning_orders o on o.id=a.order_id where not exists(select 1 from public.learning_instructor_earnings e where e.allocation_id=a.id)
  union all select 'reversed_order_active_allocation',o.order_reference,'Refunded or chargeback order retains an unreversed commercial allocation' from public.learning_commercial_allocations a join public.learning_orders o on o.id=a.order_id where o.status in ('refunded','chargeback') and a.status<>'reversed'
  union all select 'available_earning_without_release',o.order_reference,'Available instructor earning has no release ledger transaction' from public.learning_instructor_earnings e join public.learning_commercial_allocations a on a.id=e.allocation_id join public.learning_orders o on o.id=a.order_id where e.status='available' and not exists(select 1 from public.learning_instructor_earning_events ev join public.learning_ledger_transactions t on t.id=ev.ledger_transaction_id where ev.earning_id=e.id and ev.event_type='earning.available' and t.transaction_type='instructor_earnings_release')
  union all select 'matured_held_earning',o.order_reference,'Instructor earning is past its 14-day availability time and remains held without an active financial-protection case' from public.learning_instructor_earnings e join public.learning_commercial_allocations a on a.id=e.allocation_id join public.learning_orders o on o.id=a.order_id where e.status='held' and e.available_at<now() and not exists(select 1 from public.learning_payment_cases c where c.order_id=a.order_id and c.status in ('requested','submitting','pending','processing','needs_attention','opened','action_required','submitted','under_review'));
$function$;

-- New orders snapshot the active version. Existing rows retain their original immutable snapshots.
create or replace function public.initialize_paystack_test_learning_order(p_learner_id uuid,p_course_id bigint)
returns table(order_id bigint,order_reference text,payment_attempt_id bigint,amount_minor bigint,currency text) language plpgsql security definer set search_path to '' as $function$
declare course_row record; order_key bigint; order_ref text; attempt_key bigint; amount_key bigint; terms_version text;
begin
  if p_learner_id is null or p_course_id is null then raise exception 'Learner and course are required' using errcode='22023'; end if;
  if not exists(select 1 from public.learning_paystack_test_fixtures fixture where fixture.course_id=p_course_id and fixture.tester_id=p_learner_id and fixture.status='active' and fixture.expires_at>now()) then raise exception 'Learner is not eligible for this controlled test checkout' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_learner_id::text||':'||p_course_id::text,0));
  if not exists(select 1 from public.profiles where id=p_learner_id) then raise exception 'Learner profile was not found' using errcode='P0002'; end if;
  select c.id,c.instructor_id,c.title,c.price_amount,c.price_currency,c.is_free,c.is_limited_time_free,c.status,p.full_name instructor_name into course_row from public.learning_courses c left join public.profiles p on p.id=c.instructor_id where c.id=p_course_id;
  if not found or course_row.status<>'published' then raise exception 'Course is not available for purchase' using errcode='22023'; end if;
  if course_row.is_free or course_row.is_limited_time_free or course_row.price_amount is null or course_row.price_amount<=0 or course_row.price_currency<>'NGN' or scale(course_row.price_amount)>2 then raise exception 'Course does not have an eligible paid NGN price' using errcode='22023'; end if;
  if exists(select 1 from public.enrollments where learner_id=p_learner_id and course_id=p_course_id and status in ('active','completed')) or exists(select 1 from public.learning_course_entitlements where learner_id=p_learner_id and course_id=p_course_id and status='active') then raise exception 'Learner already has course access' using errcode='23505'; end if;
  if exists(select 1 from public.learning_orders where learner_id=p_learner_id and course_id=p_course_id and status in ('created','payment_pending','paid','partially_refunded')) then raise exception 'A purchase already exists for this course' using errcode='23505'; end if;
  amount_key:=round(course_row.price_amount*100)::bigint; terms_version:=public.resolve_learning_commercial_terms_version(course_row.id,course_row.instructor_id);
  insert into public.learning_orders(learner_id,course_id,instructor_id,course_title_snapshot,instructor_name_snapshot,gross_amount_minor,currency,status,commercial_terms_version) values(p_learner_id,p_course_id,course_row.instructor_id,course_row.title,course_row.instructor_name,amount_key,'NGN','created',terms_version) returning id,learning_orders.order_reference into order_key,order_ref;
  insert into public.learning_payment_attempts(order_id,provider,provider_reference,amount_minor,currency,status,paystack_domain) values(order_key,'paystack',order_ref,amount_key,'NGN','initialized','test') returning id into attempt_key;
  return query select order_key,order_ref,attempt_key,amount_key,'NGN'::text;
end;$function$;

-- Allocation is intentionally appended after the original capture; the capture remains the source financial event.
create or replace function public.finalize_paystack_test_charge(p_provider_event_id text,p_payload_digest text,p_reference text,p_provider_transaction_id text,p_amount_minor bigint,p_currency text,p_domain text,p_payload jsonb)
returns table(outcome text,order_id bigint,enrollment_id bigint) language plpgsql security definer set search_path to '' as $function$
declare attempt_row record; event_row record; event_key bigint; enrollment_key bigint; ledger_key bigint;
begin
  if p_domain<>'test' or p_currency<>'NGN' or p_amount_minor<=0 or p_payload_digest !~ '^[a-f0-9]{64}$' or p_provider_event_id is null or p_provider_transaction_id is null then raise exception 'Invalid Paystack test event' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('paystack:'||p_reference,0));
  select a.id attempt_id,a.order_id,a.amount_minor,a.currency,a.status attempt_status,o.learner_id,o.course_id,o.status order_status,o.gross_amount_minor into attempt_row from public.learning_payment_attempts a join public.learning_orders o on o.id=a.order_id where a.provider='paystack' and a.provider_reference=p_reference and coalesce(a.paystack_domain,'test')='test' for update of a,o;
  if not found then
    if exists(select 1 from public.learning_payment_attempts where provider='paystack' and provider_reference=p_reference and coalesce(paystack_domain,'test')<>'test') then
      raise exception 'Paystack test event cannot target a non-test payment attempt' using errcode='22023';
    end if;
    insert into public.learning_payment_provider_events(provider,provider_event_id,event_type,payload_digest,payload,signature_valid,processing_status,processed_at,processing_error) values('paystack',p_provider_event_id,'charge.success',p_payload_digest,p_payload,true,'ignored',now(),'No matching Growvelt Learning payment attempt') on conflict(provider,provider_event_id) do nothing;
    return query select 'unknown_reference'::text,null::bigint,null::bigint; return;
  end if;
  select * into event_row from public.learning_payment_provider_events where provider='paystack' and provider_event_id=p_provider_event_id for update;
  if found then if event_row.payload_digest<>p_payload_digest then return query select 'duplicate_payload_mismatch'::text,attempt_row.order_id,null::bigint; return; end if; if event_row.processing_status='processed' then select e.enrollment_id into enrollment_key from public.learning_course_entitlements e where e.order_id=attempt_row.order_id; return query select 'already_processed'::text,attempt_row.order_id,enrollment_key; return; end if; event_key:=event_row.id; update public.learning_payment_provider_events set processing_status='received',processed_at=null,processing_error=null,order_id=attempt_row.order_id,payment_attempt_id=attempt_row.attempt_id where id=event_key; else insert into public.learning_payment_provider_events(provider,provider_event_id,event_type,payload_digest,payload,signature_valid,order_id,payment_attempt_id) values('paystack',p_provider_event_id,'charge.success',p_payload_digest,p_payload,true,attempt_row.order_id,attempt_row.attempt_id) returning id into event_key; end if;
  if attempt_row.amount_minor<>p_amount_minor or attempt_row.gross_amount_minor<>p_amount_minor or attempt_row.currency<>p_currency then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Verified provider amount or currency did not match the order' where id=event_key; return query select 'amount_mismatch'::text,attempt_row.order_id,null::bigint; return; end if;
  if attempt_row.learner_id is null or attempt_row.course_id is null then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Order identity was detached before finalization' where id=event_key; return query select 'detached_order'::text,attempt_row.order_id,null::bigint; return; end if;
  if attempt_row.order_status in ('paid','partially_refunded','refunded','chargeback') then update public.learning_payment_provider_events set processing_status='processed',processed_at=now() where id=event_key; select e.enrollment_id into enrollment_key from public.learning_course_entitlements e where e.order_id=attempt_row.order_id; return query select 'already_paid'::text,attempt_row.order_id,enrollment_key; return; end if;
  if attempt_row.order_status='created' then update public.learning_orders set status='payment_pending' where id=attempt_row.order_id; end if;
  if attempt_row.order_status not in ('created','payment_pending') then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Order is not payable' where id=event_key; return query select 'order_not_payable'::text,attempt_row.order_id,null::bigint; return; end if;
  update public.learning_payment_attempts set status='succeeded',verified_at=now(),failed_at=null,failure_code=null,failure_message=null,provider_transaction_id=p_provider_transaction_id where id=attempt_row.attempt_id;
  update public.learning_orders set status='paid',paid_at=now(),cancelled_at=null where id=attempt_row.order_id;
  insert into public.learning_ledger_transactions(order_id,transaction_type,currency,description) values(attempt_row.order_id,'payment_capture','NGN','Verified Paystack test-mode course payment') returning id into ledger_key;
  insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values(ledger_key,1,'asset.paystack_receivable',p_amount_minor,'NGN','payment_provider',p_provider_transaction_id),(ledger_key,2,'liability.marketplace_sales_unallocated',-p_amount_minor,'NGN','learning_order',p_reference);
  perform public.allocate_learning_order_commercial_terms(attempt_row.order_id,null);
  insert into public.enrollments(learner_id,course_id,status) values(attempt_row.learner_id,attempt_row.course_id,'active') on conflict(learner_id,course_id) do update set status='active',completed_at=null returning id into enrollment_key;
  insert into public.learning_course_entitlements(learner_id,course_id,order_id,enrollment_id,status) values(attempt_row.learner_id,attempt_row.course_id,attempt_row.order_id,enrollment_key,'active');
  update public.learning_payment_provider_events set processing_status='processed',processed_at=now(),processing_error=null where id=event_key;
  return query select 'paid_and_enrolled'::text,attempt_row.order_id,enrollment_key;
end;$function$;

-- Existing test-mode refund and chargeback state machines remain authoritative.
-- Their only new behavior is an idempotent compensating allocation reversal.
create or replace function public.finalize_paystack_test_full_refund(p_case_id bigint,p_provider_event_id bigint,p_provenance text,p_operator_id uuid default null)
returns table(outcome text,order_id bigint,ledger_transaction_id bigint) language plpgsql security definer set search_path to '' as $function$
declare case_row record; entitlement_row record; provider_amount_minor bigint; ledger_key bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended('refund-case:'||p_case_id::text,0));
 select c.*,o.order_reference,o.status order_status,o.gross_amount_minor,o.learner_id,o.course_id into case_row from public.learning_payment_cases c join public.learning_orders o on o.id=c.order_id where c.id=p_case_id and c.case_type='refund' for update of c,o;
 if not found then raise exception 'Refund case not found' using errcode='P0002'; end if;
 select id into ledger_key from public.learning_ledger_transactions where payment_case_id=p_case_id and transaction_type='refund';
 if ledger_key is not null then return query select 'already_processed',case_row.order_id,ledger_key; return; end if;
 if case_row.provider_status<>'processed' or case_row.amount_minor<>case_row.gross_amount_minor then raise exception 'Authoritative processed full refund required' using errcode='22023'; end if;
 select nullif(ev.payload->>'amount','')::bigint into provider_amount_minor
 from public.learning_payment_provider_events ev
 where ev.id=p_provider_event_id and ev.payment_case_id=p_case_id and ev.event_type='refund.processed'
   and (ev.signature_valid or ev.verification_source='provider_api') for share;
 if provider_amount_minor is null or provider_amount_minor<>case_row.gross_amount_minor then
   raise exception 'Authoritative processed refund amount does not match the order gross amount' using errcode='22023';
 end if;
 if case_row.order_status<>'paid' then raise exception 'Order is not refundable' using errcode='22023'; end if;
 update public.learning_payment_cases set status='processed',processed_amount_minor=provider_amount_minor,processed_at=coalesce(processed_at,now()),resolved_at=coalesce(resolved_at,now()),last_verified_at=now() where id=p_case_id;
 perform public.reverse_learning_order_commercial_allocation(case_row.order_id,p_case_id,'processed Paystack full refund',p_operator_id);
 insert into public.learning_ledger_transactions(order_id,payment_case_id,transaction_type,currency,description,created_by) values(case_row.order_id,p_case_id,'refund',case_row.currency,'Processed Paystack full course refund',p_operator_id) returning id into ledger_key;
 insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values(ledger_key,1,'liability.marketplace_sales_unallocated',case_row.amount_minor,case_row.currency,'payment_case',case_row.case_reference::text),(ledger_key,2,'asset.paystack_receivable',-case_row.amount_minor,case_row.currency,'payment_provider',coalesce(case_row.provider_case_id,case_row.provider_case_reference));
 update public.learning_orders set status='refunded' where id=case_row.order_id;
 update public.learning_course_entitlements e set status='refunded',revoked_at=now(),revocation_reason='Full Paystack refund processed' where e.order_id=case_row.order_id and e.status='active' returning e.id,e.enrollment_id into entitlement_row;
 if not found then raise exception 'Active entitlement not found' using errcode='P0002'; end if;
 update public.enrollments set status='cancelled' where id=entitlement_row.enrollment_id and learner_id=case_row.learner_id and course_id=case_row.course_id and status in('active','completed');
 if not found then raise exception 'Active or completed enrollment not found' using errcode='P0002'; end if;
 update public.learning_payment_cases set status='processed',processed_amount_minor=amount_minor,processed_at=now(),resolved_at=now(),last_verified_at=now() where id=p_case_id;
 insert into public.learning_payment_case_events(payment_case_id,event_type,normalized_status,provenance,provider_event_id,operator_id,metadata) values(p_case_id,'refund.processed','processed',p_provenance,p_provider_event_id,p_operator_id,jsonb_build_object('ledger_transaction_id',ledger_key));
 insert into public.learning_audit_events(actor_user_id,actor_role,action,entity_type,entity_id,metadata) values(p_operator_id,case when p_operator_id is null then 'payment_system' else 'admin_operator' end,'refund.processed','payment_case',p_case_id::text,jsonb_build_object('order_id',case_row.order_id,'ledger_transaction_id',ledger_key,'amount_minor',case_row.amount_minor));
 return query select 'refunded',case_row.order_id,ledger_key;
end;$function$;

create or replace function public.finalize_paystack_test_chargeback(p_case_id bigint,p_provider_event_id bigint,p_provenance text,p_operator_id uuid)
returns table(outcome text,order_id bigint,ledger_transaction_id bigint) language plpgsql security definer set search_path to '' as $function$
declare case_row record; ledger_key bigint; entitlement_row record; reversed_minor bigint;
begin
  if p_provenance not in ('webhook','provider_api') then raise exception 'Invalid chargeback provenance' using errcode='22023'; end if;
  select c.*,o.status order_status,o.gross_amount_minor into case_row from public.learning_payment_cases c join public.learning_orders o on o.id=c.order_id where c.id=p_case_id and c.case_type='chargeback' for update of c,o;
  if not found then raise exception 'Dispute case not found' using errcode='P0002'; end if;
  select id into ledger_key from public.learning_ledger_transactions where payment_case_id=p_case_id and transaction_type='chargeback';
  if found then return query select 'already_finalized',case_row.order_id,ledger_key; return; end if;
  if case_row.status='won' then raise exception 'Won dispute cannot create a chargeback' using errcode='22023'; end if;
  select coalesce(sum(abs(e.amount_minor))/2,0) into reversed_minor from public.learning_ledger_transactions t join public.learning_ledger_entries e on e.transaction_id=t.id where t.order_id=case_row.order_id and t.transaction_type in ('refund','chargeback');
  if case_row.order_status<>'paid' or reversed_minor+case_row.amount_minor>case_row.gross_amount_minor then raise exception 'Chargeback exceeds remaining paid balance' using errcode='22023'; end if;
  -- Set the authoritative provider outcome before the commercial reversal. If
  -- the reversal rejects a partial chargeback, this transaction rolls back and
  -- the signed/provider event remains available for explicit operator review.
  update public.learning_payment_cases set status='lost',provider_status='resolved',provider_resolution='merchant-accepted',provider_resolved_at=now(),resolved_at=now(),last_verified_at=now() where id=p_case_id;
  perform public.reverse_learning_order_commercial_allocation(case_row.order_id,p_case_id,'Paystack dispute financial loss',p_operator_id);
  insert into public.learning_ledger_transactions(order_id,payment_case_id,transaction_type,currency,description,created_by) values(case_row.order_id,p_case_id,'chargeback',case_row.currency,'Paystack dispute financial loss',p_operator_id) returning id into ledger_key;
  insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values(ledger_key,1,'liability.marketplace_sales_unallocated',case_row.amount_minor,case_row.currency,'payment_case',case_row.case_reference::text),(ledger_key,2,'asset.paystack_receivable',-case_row.amount_minor,case_row.currency,'paystack_dispute',case_row.provider_case_id);
  update public.learning_orders set status='chargeback',updated_at=now() where id=case_row.order_id;
  update public.learning_course_entitlements e set status='chargeback',revoked_at=now(),revocation_reason='Paystack dispute resolved against Growvelt' where e.order_id=case_row.order_id and e.status='active' returning e.id,e.enrollment_id into entitlement_row;
  if entitlement_row.enrollment_id is not null then update public.enrollments set status='cancelled' where id=entitlement_row.enrollment_id and status in('active','completed'); end if;
  update public.learning_payment_cases set status='lost',processed_amount_minor=amount_minor,processed_at=now(),resolved_at=now(),provider_resolved_at=now(),last_verified_at=now() where id=p_case_id;
  insert into public.learning_payment_case_events(payment_case_id,event_type,normalized_status,provenance,provider_event_id,operator_id,metadata) values(p_case_id,'dispute.lost','lost',p_provenance,p_provider_event_id,p_operator_id,jsonb_build_object('ledger_transaction_id',ledger_key));
  insert into public.learning_audit_events(actor_user_id,actor_role,action,entity_type,entity_id,metadata) values(p_operator_id,case when p_operator_id is null then 'payment_system' else 'admin_operator' end,'chargeback.finalized','payment_case',p_case_id::text,jsonb_build_object('order_id',case_row.order_id,'ledger_transaction_id',ledger_key,'amount_minor',case_row.amount_minor));
  return query select 'chargeback_finalized',case_row.order_id,ledger_key;
end;$function$;

create or replace function public.initialize_paystack_live_learning_order(p_learner_id uuid,p_course_id bigint)
returns table(order_id bigint,order_reference text,payment_attempt_id bigint,amount_minor bigint,currency text) language plpgsql security definer set search_path to '' as $function$
declare course_row record; order_key bigint; order_ref text; attempt_key bigint; amount_key bigint; terms_version text;
begin
  if p_learner_id is null or p_course_id is null then raise exception 'Learner and course are required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('paystack:live:'||p_learner_id::text||':'||p_course_id::text,0));
  if not exists(select 1 from public.profiles where id=p_learner_id) then raise exception 'Learner profile was not found' using errcode='P0002'; end if;
  select c.id,c.instructor_id,c.title,c.price_amount,c.price_currency,c.is_free,c.is_limited_time_free,c.status,p.full_name instructor_name into course_row from public.learning_courses c left join public.profiles p on p.id=c.instructor_id where c.id=p_course_id;
  if not found or course_row.status<>'published' then raise exception 'Course is not available for purchase' using errcode='22023'; end if;
  if course_row.is_free or course_row.is_limited_time_free or course_row.price_amount is null or course_row.price_amount<=0 or course_row.price_currency<>'NGN' or scale(course_row.price_amount)>2 then raise exception 'Course does not have an eligible paid NGN price' using errcode='22023'; end if;
  if exists(select 1 from public.enrollments where learner_id=p_learner_id and course_id=p_course_id and status in ('active','completed')) or exists(select 1 from public.learning_course_entitlements where learner_id=p_learner_id and course_id=p_course_id and status='active') or exists(select 1 from public.learning_orders where learner_id=p_learner_id and course_id=p_course_id and status in ('created','payment_pending','paid','partially_refunded')) then raise exception 'Learner already has course access or a purchase in progress' using errcode='23505'; end if;
  amount_key:=round(course_row.price_amount*100)::bigint; terms_version:=public.resolve_learning_commercial_terms_version(course_row.id,course_row.instructor_id);
  insert into public.learning_orders(learner_id,course_id,instructor_id,course_title_snapshot,instructor_name_snapshot,gross_amount_minor,currency,status,commercial_terms_version) values(p_learner_id,p_course_id,course_row.instructor_id,course_row.title,course_row.instructor_name,amount_key,'NGN','created',terms_version) returning id,public.learning_orders.order_reference into order_key,order_ref;
  insert into public.learning_payment_attempts(order_id,provider,provider_reference,amount_minor,currency,status,paystack_domain) values(order_key,'paystack',order_ref,amount_key,'NGN','initialized','live') returning id into attempt_key;
  return query select order_key,order_ref,attempt_key,amount_key,'NGN'::text;
end;$function$;

create or replace function public.finalize_paystack_live_charge(p_provider_event_id text,p_payload_digest text,p_reference text,p_provider_transaction_id text,p_amount_minor bigint,p_currency text,p_domain text,p_payload jsonb)
returns table(outcome text,order_id bigint,enrollment_id bigint) language plpgsql security definer set search_path to '' as $function$
declare attempt_row record; event_row record; event_key bigint; enrollment_key bigint; ledger_key bigint;
begin
  if p_domain<>'live' or p_currency<>'NGN' or p_amount_minor<=0 or p_payload_digest !~ '^[a-f0-9]{64}$' or p_provider_event_id is null or p_provider_transaction_id is null then raise exception 'Invalid Paystack live event' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('paystack:live:'||p_reference,0));
  select a.id attempt_id,a.order_id,a.amount_minor,a.currency,o.learner_id,o.course_id,o.status order_status,o.gross_amount_minor into attempt_row from public.learning_payment_attempts a join public.learning_orders o on o.id=a.order_id where a.provider='paystack' and a.provider_reference=p_reference and a.paystack_domain='live' for update of a,o;
  if not found then insert into public.learning_payment_provider_events(provider,provider_event_id,event_type,payload_digest,payload,signature_valid,processing_status,processed_at,processing_error) values('paystack',p_provider_event_id,'charge.success',p_payload_digest,p_payload,true,'ignored',now(),'No matching Growvelt Learning live payment attempt') on conflict(provider,provider_event_id) do nothing; return query select 'unknown_reference'::text,null::bigint,null::bigint; return; end if;
  select * into event_row from public.learning_payment_provider_events where provider='paystack' and provider_event_id=p_provider_event_id for update;
  if found then if event_row.payload_digest<>p_payload_digest then return query select 'duplicate_payload_mismatch'::text,attempt_row.order_id,null::bigint; return; end if; if event_row.processing_status='processed' then select e.enrollment_id into enrollment_key from public.learning_course_entitlements e where e.order_id=attempt_row.order_id; return query select 'already_processed'::text,attempt_row.order_id,enrollment_key; return; end if; event_key:=event_row.id; update public.learning_payment_provider_events set processing_status='received',processed_at=null,processing_error=null,order_id=attempt_row.order_id,payment_attempt_id=attempt_row.attempt_id where id=event_key; else insert into public.learning_payment_provider_events(provider,provider_event_id,event_type,payload_digest,payload,signature_valid,order_id,payment_attempt_id) values('paystack',p_provider_event_id,'charge.success',p_payload_digest,p_payload,true,attempt_row.order_id,attempt_row.attempt_id) returning id into event_key; end if;
  if attempt_row.amount_minor<>p_amount_minor or attempt_row.gross_amount_minor<>p_amount_minor or attempt_row.currency<>p_currency then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Verified provider amount or currency did not match the order' where id=event_key; return query select 'amount_mismatch'::text,attempt_row.order_id,null::bigint; return; end if;
  if attempt_row.learner_id is null or attempt_row.course_id is null then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Order identity was detached before finalization' where id=event_key; return query select 'detached_order'::text,attempt_row.order_id,null::bigint; return; end if;
  if attempt_row.order_status in ('paid','partially_refunded','refunded','chargeback') then update public.learning_payment_provider_events set processing_status='processed',processed_at=now() where id=event_key; select e.enrollment_id into enrollment_key from public.learning_course_entitlements e where e.order_id=attempt_row.order_id; return query select 'already_paid'::text,attempt_row.order_id,enrollment_key; return; end if;
  if attempt_row.order_status='created' then update public.learning_orders set status='payment_pending' where id=attempt_row.order_id; end if;
  if attempt_row.order_status not in ('created','payment_pending') then update public.learning_payment_provider_events set processing_status='failed',processed_at=now(),processing_error='Order is not payable' where id=event_key; return query select 'order_not_payable'::text,attempt_row.order_id,null::bigint; return; end if;
  update public.learning_payment_attempts set status='succeeded',verified_at=now(),failed_at=null,failure_code=null,failure_message=null,provider_transaction_id=p_provider_transaction_id where id=attempt_row.attempt_id;
  update public.learning_orders set status='paid',paid_at=now(),cancelled_at=null where id=attempt_row.order_id;
  insert into public.learning_ledger_transactions(order_id,transaction_type,currency,description) values(attempt_row.order_id,'payment_capture','NGN','Verified Paystack live-mode course payment') returning id into ledger_key;
  insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values(ledger_key,1,'asset.paystack_receivable',p_amount_minor,'NGN','payment_provider',p_provider_transaction_id),(ledger_key,2,'liability.marketplace_sales_unallocated',-p_amount_minor,'NGN','learning_order',p_reference);
  perform public.allocate_learning_order_commercial_terms(attempt_row.order_id,null);
  insert into public.enrollments(learner_id,course_id,status) values(attempt_row.learner_id,attempt_row.course_id,'active') on conflict(learner_id,course_id) do update set status='active',completed_at=null returning id into enrollment_key;
  insert into public.learning_course_entitlements(learner_id,course_id,order_id,enrollment_id,status) values(attempt_row.learner_id,attempt_row.course_id,attempt_row.order_id,enrollment_key,'active');
  update public.learning_payment_provider_events set processing_status='processed',processed_at=now(),processing_error=null where id=event_key;
  return query select 'paid_and_enrolled'::text,attempt_row.order_id,enrollment_key;
end;$function$;

revoke all on function public.prevent_learning_commercial_terms_mutation(),public.prevent_learning_commercial_allocation_mutation(),public.prevent_learning_instructor_earning_mutation(),public.prevent_learning_instructor_earning_event_mutation(),public.resolve_learning_commercial_terms_version(bigint,uuid),public.allocate_learning_order_commercial_terms(bigint,uuid),public.release_matured_learning_instructor_earnings(integer,uuid),public.reverse_learning_order_commercial_allocation(bigint,bigint,text,uuid),public.reconcile_learning_commercial_allocations(),public.initialize_paystack_test_learning_order(uuid,bigint),public.finalize_paystack_test_charge(text,text,text,text,bigint,text,text,jsonb),public.finalize_paystack_test_full_refund(bigint,bigint,text,uuid),public.finalize_paystack_test_chargeback(bigint,bigint,text,uuid),public.initialize_paystack_live_learning_order(uuid,bigint),public.finalize_paystack_live_charge(text,text,text,text,bigint,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.prevent_learning_commercial_terms_mutation(),public.prevent_learning_commercial_allocation_mutation(),public.prevent_learning_instructor_earning_mutation(),public.prevent_learning_instructor_earning_event_mutation(),public.resolve_learning_commercial_terms_version(bigint,uuid),public.allocate_learning_order_commercial_terms(bigint,uuid),public.release_matured_learning_instructor_earnings(integer,uuid),public.reverse_learning_order_commercial_allocation(bigint,bigint,text,uuid),public.reconcile_learning_commercial_allocations(),public.initialize_paystack_test_learning_order(uuid,bigint),public.finalize_paystack_test_charge(text,text,text,text,bigint,text,text,jsonb),public.finalize_paystack_test_full_refund(bigint,bigint,text,uuid),public.finalize_paystack_test_chargeback(bigint,bigint,text,uuid),public.initialize_paystack_live_learning_order(uuid,bigint),public.finalize_paystack_live_charge(text,text,text,text,bigint,text,text,jsonb) to postgres,service_role;

